<?php
namespace App\Entity;use Doctrine\DBAL\Types\Types;use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity]
class FuelDelivery{
 #[ORM\Id,ORM\GeneratedValue,ORM\Column]private ?int $id=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:false)]private ?Stations $station=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:false)]private ?FuelTank $tank=null;#[ORM\Column(length:120)]private string $supplier='';#[ORM\Column(length:60,nullable:true)]private ?string $invoiceNumber=null;#[ORM\Column(type:Types::DATE_IMMUTABLE)]private ?\DateTimeImmutable $deliveryDate=null;#[ORM\Column(type:Types::DECIMAL,precision:15,scale:3)]private string $quantity='0';#[ORM\Column(type:Types::DECIMAL,precision:15,scale:2)]private string $unitCost='0';#[ORM\Column(type:Types::DECIMAL,precision:15,scale:2)]private string $totalAmount='0';#[ORM\Column]private ?\DateTimeImmutable $createdAt=null;
 public function getId():?int{return $this->id;}public function getStation():?Stations{return $this->station;}public function setStation(Stations $v):static{$this->station=$v;return $this;}public function getTank():?FuelTank{return $this->tank;}public function setTank(FuelTank $v):static{$this->tank=$v;return $this;}public function getSupplier():string{return $this->supplier;}public function setSupplier(string $v):static{$this->supplier=$v;return $this;}public function getInvoiceNumber():?string{return $this->invoiceNumber;}public function setInvoiceNumber(?string $v):static{$this->invoiceNumber=$v;return $this;}public function getDeliveryDate():?\DateTimeImmutable{return $this->deliveryDate;}public function setDeliveryDate(\DateTimeImmutable $v):static{$this->deliveryDate=$v;return $this;}public function getQuantity():string{return $this->quantity;}public function setQuantity(string $v):static{$this->quantity=$v;return $this;}public function getUnitCost():string{return $this->unitCost;}public function setUnitCost(string $v):static{$this->unitCost=$v;return $this;}public function getTotalAmount():string{return $this->totalAmount;}public function setTotalAmount(string $v):static{$this->totalAmount=$v;return $this;}public function getCreatedAt():?\DateTimeImmutable{return $this->createdAt;}public function setCreatedAt(\DateTimeImmutable $v):static{$this->createdAt=$v;return $this;}
}
